using System.Text.RegularExpressions;
using System.Text.Json.Nodes;
namespace Axis.Core.Projects;
public static partial class ControlEngine {
 static readonly Regex SUPERSEDED=new(@"(superseded|supersedes|do not merge|no longer authorized|rejected as unnecessary|no runtime integration authorized)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex BLOCKED=new(@"\b(blocked|blocker|cannot proceed|can't proceed|stuck|waiting on|waiting for|requires? .{0,80} before|dependency missing|access missing)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex RESOLVED_BLOCK=new(@"\b(no longer|not|isn't|is not)\s+(?:blocked|stuck|waiting)|\bblocker\s+(?:cleared|resolved|removed)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex TEST=new(@"\b(needs? (?:a )?(?:live|physical|hardware|real user|smoke)?\s*test|retest|test needed|validation pending|needs? validation|verify|validate|run (?:the )?.{0,50}\btest|physical gate|live test|smoke test|compatibility test|acceptance test)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex CLOSED=new(@"\b(done|complete|completed|closed|merged|accepted|validated|resolved|fixed|working|works|shipped|green|passed|pass)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex NO_REMAINING=new(@"\b(no remaining work|nothing left|no further action|no action required|fully complete|closeout complete|finished)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex OPEN=new(@"\b(next|next step|todo|to-do|remaining|still needs?|needs? to|must|should|continue|implement|build|fix|update|create|finish|send|reply|compare|choose|review|audit|install|configure|calibrate|scan|sync|deploy|merge|open|run|launch)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex GENERIC=new(@"^(?:continue|resume) in the synced chatgpt thread\.?$|^chatgpt thread synced\.?$|^review the newest evidence and choose the next safe action\.?$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex POSITIVE_GITHUB=new(@"(real user pass|physical pass|accepted|merged|complete\b|completed\b|stable|validated|success\b|green\b)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex PENDING_GITHUB=new(@"(needs? test|requires? (?:a )?(?:live|physical|hardware)?\s*test|live test needed|physical (gate|validation|acceptance).*pending|pending.*physical|smoke pending|scope audit required|retest|test needed|validation pending|still needs? to\b|needs? to (?:be )?(?:load|run|verify|validate|test|pass|check)\b|physical gate\b|unresolved .*validation)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex BLOCKED_GITHUB=new(@"(blocked|blocker|cannot proceed|waiting on|requires hardware|hardware test|physical validation pending|unresolved gate|unresolved .*physical)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 static readonly Regex DONE_GITHUB=new(@"(program closeout.*complete|phase\s*\d+.*complete|done\b|final closeout)",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
}
